import * as THREE from 'three/webgpu';
import { color, mix, linearSRGB, vec2 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const resources = { timelines: [], geoms: [], mats: [] };

  // === DIMENSIONS & PALETTE ===
  const W = 3.4, H = 1.9, hairline = 0.006;
  const C = {
    gradTop: new THREE.Color('#1a1a22'),
    gradBot: new THREE.Color('#111116'),
    border: new THREE.Color('#26262f'),
    accent: new THREE.Color('#ff2a38'),
    text: new THREE.Color('#e8ecf2'),
  };

  // === PANEL BACKGROUND ===
  const panelGeo = new THREE.PlaneGeometry(W, H);
  resources.geoms.push(panelGeo);

  const panelMat = new THREE.MeshStandardNodeMaterial({
    colorNode: mix(
      linearSRGB(color(C.gradTop)),
      linearSRGB(color(C.gradBot)),
      vec2().y.remap(-H / 2, H / 2, 0, 1)
    ),
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
    opacity: 0,
  });
  resources.mats.push(panelMat);

  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.y = 0.2;
  group.add(panel);

  // === HAIRLINE BORDERS ===
  const borderMat = new THREE.MeshStandardNodeMaterial({
    color: C.border,
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
    opacity: 0,
  });
  resources.mats.push(borderMat);

  const createBorder = (w, h, x, y) => {
    const g = new THREE.PlaneGeometry(w, h);
    resources.geoms.push(g);
    const m = new THREE.Mesh(g, borderMat);
    m.position.set(x, y, 0.001);
    return m;
  };

  const borders = [
    createBorder(W, hairline, 0, H / 2 - hairline / 2),
    createBorder(W, hairline, 0, -H / 2 + hairline / 2),
    createBorder(hairline, H, -W / 2 + hairline / 2, 0),
    createBorder(hairline, H, W / 2 - hairline / 2, 0),
  ];
  borders.forEach(b => group.add(b));

  // === TEXT POSITIONING GRID ===
  const quoteMarkY = H / 2 - 0.5;
  const quoteY = quoteMarkY - 0.25;
  const attrY = quoteY - 0.25;
  const captionY = attrY - 0.15;

  // === QUOTATION MARK ===
  const quoteMark = ctx.fontAtlas.createText('""', {
    font: 'Lora',
    size: 0.62,
    weight: 600,
    color: C.accent,
  });
  quoteMark.position.set(-W / 2 + 0.5, quoteMarkY, 0.04);
  quoteMark.scale.set(1.04, 1.04, 1.04);
  group.add(quoteMark);

  // === QUOTE TEXT ===
  const quoteText = ctx.fontAtlas.createText(
    '"The bezel action alone is worth the wait. Nothing else on my wrist feels this considered."',
    {
      font: 'Lora',
      size: 0.2,
      weight: 400,
      color: C.text,
      maxWidth: 2.4,
      lineHeight: 1.45,
    }
  );
  quoteText.position.set(-1.2, quoteY, 0.03);
  group.add(quoteText);

  // === ACCENT RULE ===
  const accentGeo = new THREE.PlaneGeometry(0.2, 0.02);
  resources.geoms.push(accentGeo);

  const accentMat = new THREE.MeshStandardNodeMaterial({
    color: C.accent,
    emissive: C.accent,
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0,
    transparent: true,
    opacity: 0,
  });
  resources.mats.push(accentMat);

  const accentRule = new THREE.Mesh(accentGeo, accentMat);
  accentRule.position.set(-W / 2 + 0.5, attrY + 0.05, 0.035);
  group.add(accentRule);

  // === ATTRIBUTION ===
  const attribution = ctx.fontAtlas.createText('M. OKAFOR', {
    font: 'JetBrains Mono',
    size: 0.13,
    weight: 700,
    color: C.text,
    letterSpacing: 0.08,
  });
  attribution.position.set(-W / 2 + 0.75, attrY, 0.03);
  group.add(attribution);

  // === CAPTION ===
  const caption = ctx.fontAtlas.createText('COLLECTOR SINCE 2019', {
    font: 'JetBrains Mono',
    size: 0.09,
    weight: 400,
    color: C.text,
    letterSpacing: 0.12,
  });
  caption.position.set(-W / 2 + 0.75, captionY, 0.03);
  group.add(caption);

  // === ANIMATIONS ===
  const timeline = gsap.timeline();

  // Panel fade-up: y 0.2 -> 0, opacity 0 -> 1
  timeline.to(panel.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  }, 0);

  timeline.to(panelMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  }, 0);

  timeline.to(borderMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  }, 0);

  timeline.to(accentMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  }, 0);

  // Quote mark weighted-settle: scale 1.04 -> 1.0
  timeline.to(quoteMark.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
  }, 0.1);

  resources.timelines.push(timeline);

  // === CLEANUP ===
  group.userData.cleanup = () => {
    resources.timelines.forEach(t => t.kill());
    resources.geoms.forEach(g => g.dispose());
    resources.mats.forEach(m => m.dispose());
  };

  return group;
}
